{
  "subtype": "faceted_decomposition",
  "concept": "airline_service_quality",
  "per_column": [
    {
      "name": "staff_interaction_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Cabin/staff interaction (friendly, rude, indifferent) is a core constitutive aspect OF service quality — the human-service dimension. Clear part-of relationship."
    },
    {
      "name": "food_quality_assessment",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Catering/food quality is a genuine aspect of the in-flight service experience, an 'aspect of' service quality rather than a predictor of it."
    },
    {
      "name": "service_consistency_trend",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Consistency/reliability is a legitimate service-quality dimension, so it qualifies as a facet. However, its operationalisation as a temporal trend (improving/declining_vs_past) is a meta-property of quality rather than a static component, weakening the part-of relationship; dominated by 'first_time_no_baseline'."
    },
    {
      "name": "cabin_product_type",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "This is a categorical description of the physical product/cabin class purchased (economy, lie-flat business, suite). It is a context/segmentation variable that predicts or conditions service quality, not an assessed aspect OF it."
    },
    {
      "name": "disruption_handling_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "How the airline manages disruptions is a recognised service-recovery aspect of service quality. Part-of relationship holds."
    },
    {
      "name": "ground_service_experience",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Airport/ground handling (check-in, boarding) is a constitutive aspect of the end-to-end service experience."
    },
    {
      "name": "customer_service_resolution",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Complaint responsiveness/resolution is a genuine facet (SERVQUAL responsiveness/recovery). However it overlaps heavily with disruption_handling_quality and booking_policy_issue, both of which capture the same recovery/complaint-handling underlying aspect."
    },
    {
      "name": "booking_policy_issue",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Booking/policy handling (rebooking, refunds, seat reservations, baggage disputes) is part of the pre-flight service experience. But 'refund_or_compensation_denied' overlaps with customer_service_resolution's 'inadequate_compensation', so it is not cleanly separated from the recovery facet."
    },
    {
      "name": "haul_type",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "Long/medium/short haul is a route characteristic that contextualises or predicts service quality; it is not an aspect OF service quality itself."
    }
  ],
  "facet_columns": [
    "staff_interaction_quality",
    "food_quality_assessment",
    "service_consistency_trend",
    "disruption_handling_quality",
    "ground_service_experience",
    "customer_service_resolution",
    "booking_policy_issue"
  ],
  "non_facet_columns": [
    "cabin_product_type",
    "haul_type"
  ],
  "mutual_exclusivity": 0.55,
  "exhaustiveness": 0.65,
  "rationale": "Most added columns are genuine part-of facets of airline service quality (staff, food, ground service, disruption handling, complaint resolution, booking/policy), so the decomposition partly realises faceted MECE. Two columns are NOT facets: cabin_product_type and haul_type are external context/predictor variables (product class and route length) that condition service quality rather than constitute it. Mutual exclusivity is only moderate because the three recovery/complaint-oriented facets (disruption_handling_quality, customer_service_resolution, booking_policy_issue) overlap on the same underlying service-recovery aspect — e.g., denied compensation/refund appears in both booking_policy_issue and customer_service_resolution — and service_consistency_trend is a meta-property that blurs into overall quality. Exhaustiveness is moderate: the true facets cover human service, food, ground, and recovery/policy dimensions, but the physical in-flight experience aspects (seat comfort, in-flight entertainment quality) and value-for-money — legitimate constitutive facets of service quality — are not decomposed by the added set (they exist only as pre-existing rating columns), leaving the interactional side over-represented and the product-experience side under-covered."
}

